// 匿名ID\n  userId             String? // 用户ID\n  user               User?              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt          DateTime           @default(now()) // 创建时间\n  updatedAt          DateTime           @updatedAt // 更新时间\n  browser            String? // 浏览器信息\n  os                 String? // 操作系统信息\n  device             String? // 设备信息\n  pageViews          PageView[]\n  trackEvents        TrackEvent[]\n  performanceEntries PerformanceEntry[]\n  errorEntries       ErrorEntry[]\n\n  @@index([userId])\n  @@index([anonymousId])\n}\n\n//pv表\nmodel PageView {\n  id        String   @id @default(cuid()) // pvID\n  visitorId String // 访客ID\n  visitor   Visitor  @relation(fields: [visitorId], references: [id], onDelete: Cascade)\n  url       String // 页面URL\n  referrer  String? // 来源URL\n  path      String // 页面路径\n  createdAt DateTime @default(now()) // 创建时间\n  updatedAt DateTime @updatedAt // 更新时间\n\n  @@index([visitorId, createdAt])\n  @@index([path, createdAt])\n}\n\n//用户行为表\nmodel TrackEvent {\n  id        String   @id @default(cuid()) // 行为ID\n  visitorId String // 访客ID\n  visitor   Visitor  @relation(fields: [visitorId], references: [id], onDelete: Cascade)\n  event     String // 事件类型\n  payload   Json? // 事件数据\n  url       String? // 页面URL\n  createdAt DateTime @default(now()) // 创建时间\n  updatedAt DateTime @updatedAt // 更新时间\n\n  @@index([visitorId, createdAt])\n  @@index([event, createdAt])\n}\n\n//性能指标\nmodel PerformanceEntry {\n  id        String   @id @default(cuid()) // 性能指标ID\n  visitorId String // 访客ID\n  visitor   Visitor  @relation(fields: [visitorId], references: [id], onDelete: Cascade)\n  fp        Float? // FP\n  fcp       Float? // FCP\n  lcp       Float? // LCP\n  inp       Float? // INP\n  cls       Float? // CLS\n  createdAt DateTime @default(now()) // 创建时间\n  updatedAt DateTime @updatedAt // 更新时间\n\n  @@index([fp, createdAt])\n  @@index([fcp, createdAt])\n  @@index([lcp, createdAt])\n  @@index([inp, createdAt])\n  @@index([cls, createdAt])\n  @@index([fp, fcp, lcp, inp, cls, createdAt])\n}\n\nmodel ErrorEntry {\n  id        String   @id @default(cuid()) // 错误指标ID\n  visitorId String // 访客ID\n  visitor   Visitor  @relation(fields: [visitorId], references: [id], onDelete: Cascade)\n  error     String // 错误类型 js |promise\n  message   String? // 错误信息\n  stack     String? // 错误堆栈\n  url       String? // 页面URL\n  createdAt DateTime @default(now()) // 创建时间\n  updatedAt DateTime @updatedAt // 更新时间\n\n  @@index([visitorId, createdAt])\n  @@index([error, createdAt])\n}\n",
